package codec

import (
	"bytes"
	"encoding/binary"
	"errors"
	"fmt"
	"hash/crc32"
	"io"
	"os"
	"path/filepath"
	"sync"
)

// Channel multiplexing on top of one ReliableSession.
//
// A Mux carries several independent logical channels over a single
// reliable session. Every multiplexed message is the payload of one
// reliable data frame, prefixed by this layer's own mux header; the
// reliable wire format, the codec frame format and every established
// entry, constant and error value below this layer keep their exact
// byte-level semantics.
//
// Mux header layout inside a reliable payload (all multi-byte fields
// big-endian):
//
//		+----------+---------+--------+---------+----------+=========+
//		| chan (2) | seq (4) | fl (1) | ack (4) | crc32(4) | payload |
//		+----------+---------+--------+---------+----------+=========+
//
//	  - chan: the channel number the frame belongs to.
//	  - seq: per-channel write sequence, numbered in write order; an ack
//	    frame carries no data seq and sets it to zero.
//	  - fl: 1 = FIN, the channel's closing frame (no payload, no caller
//	    flags/kind); 2 = standalone cumulative acknowledgement. The two
//	    are never combined.
//	  - ack: cumulative "next expected" acknowledgement for chan,
//	    piggybacked on every message: every data frame of chan with seq
//	    < ack has been delivered to the reader.
//	  - crc32: IEEE CRC of the other 11 header bytes plus the payload.
//
// The reliable frame's own payload limit stays ReliableMaxPayload;
// MuxHeaderSize bytes are reserved, so the inner payload limit is
// MuxMaxPayload.
//
// Delivery guarantees:
//   - Frames within one channel are delivered in write order exactly
//     once; channels are independent, so a gap on one channel never
//     blocks another channel's delivery.
//   - The send side hands transmission opportunities out round-robin
//     across channels, so one channel sending continuously can never
//     starve the others.
//   - Every channel has its own in-flight quota; a write that finds the
//     quota full returns the established over-limit value ErrWindowFull
//     and an oversized payload returns ErrTooLarge. A rejected frame is
//     neither queued nor journaled and consumes no sequence, so it takes
//     no quota; the total buffer is bounded by Channels*Window frames.
//   - A channel opens on its first write and its write side can be
//     closed independently; its FIN rides the sequence stream like a
//     data frame. After the peer has received the channel's remaining
//     frames, the read that reaches the FIN returns io.EOF together with
//     a ChannelFrame naming the channel; other channels keep flowing.
//     Writing to, or closing, an already closed channel returns
//     ErrChannelClosed.
//
// As on the reliable layer, nothing is transmitted before Flush; after
// a restart the queue is reloaded from the journal, so Flush is also the
// retransmit operation.
const (
	// MuxHeaderSize is this layer's per-frame overhead:
	// 2 (chan) + 4 (seq) + 1 (flags) + 4 (ack) + 4 (crc32).
	MuxHeaderSize = 2 + 4 + 1 + 4 + 4

	// MuxMaxPayload is the largest payload a multiplexed data frame may
	// carry; MuxHeaderSize bytes are reserved inside the reliable
	// payload, whose own limit stays ReliableMaxPayload.
	MuxMaxPayload = ReliableMaxPayload - MuxHeaderSize

	// mux header field offsets.
	mhChanOff = 0
	mhSeqOff  = 2
	mhFlagOff = 6
	mhAckOff  = 7
	mhCRCOff  = 11
	mhBodyOff = 15

	mhFlagFin = 1 << 0
	mhFlagAck = 1 << 1
)

// ErrChannelClosed is returned by a write or a close on a channel whose
// write side has already been closed.
var ErrChannelClosed = errors.New("codec: channel closed")

// MuxConfig configures a Mux.
type MuxConfig struct {
	// Channels is the number of logical channels the session carries,
	// numbered 0..Channels-1. It must be positive.
	Channels int

	// Window is the per-channel in-flight quota in frames, enforced
	// independently for every channel (and the receive-side reach used
	// to place inbound sequences). It must be positive.
	Window int

	// StateDir holds the per-channel checkpoint files and the shared
	// replay journal used to resume the write side after a restart. It
	// is created if missing.
	StateDir string
}

// ChannelFrame is one caller-visible multiplexed frame. Channel names
// the channel it was written to.
type ChannelFrame struct {
	Channel uint16
	Flags   uint16
	Kind    uint8
	Payload []byte
}

// queuedFrame is one accepted send-side frame waiting for a
// transmission opportunity or an acknowledgement.
type queuedFrame struct {
	channel uint16
	seq     uint32
	flags   uint16
	kind    uint8
	payload []byte
	fin     bool
}

// sendChannel is one direction of one channel on the send side.
type sendChannel struct {
	// next is the next sequence a write gets; acked is the cumulative
	// "next expected" position confirmed by the peer. In-flight quota is
	// exactly next-acked because rejected frames consume no sequence.
	next   uint32
	acked  uint32
	open   bool // opened by a first write or close
	closed bool // write side closed (the FIN may still be queued)
}

// inboundFrame is a parked receive-side frame; fin markers carry no
// caller frame.
type inboundFrame struct {
	cf  ChannelFrame
	fin bool
}

// muxSeq identifies a frame within one channel.
type muxSeq struct {
	ch  uint16
	seq uint32
}

// Mux is a multiplexing layer wrapping one ReliableSession. Create it
// with NewMux; the wrapped session must not be used directly while the
// Mux owns it.
type Mux struct {
	rel *ReliableSession
	cfg MuxConfig

	mu    sync.Mutex
	queue []*queuedFrame // accepted, unacknowledged frames, arrival order
	sc    []sendChannel
	// rr is the round-robin cursor: the channel at which the next Flush
	// starts handing out opportunities.
	rr  int
	log *muxLog

	rmu sync.Mutex
	// bases is the per-channel next-due receive sequence; finEOF marks
	// channels whose FIN already reached the reader. seen remembers the
	// first copy of every sequence inside the duplicate span (the
	// window width behind the base) so a retransmitted frame that
	// conflicts with its first arrival is refused even after that
	// sequence was delivered and left held.
	bases  []uint32
	seen   map[muxSeq]inboundFrame
	held   map[muxSeq]inboundFrame
	finEOF []bool
	rerr   error

	// standCh coalesces standalone ack send requests; capacity Channels
	// keeps one pending position per channel because acks are cumulative.
	standCh   chan standAck
	stopCh    chan struct{}
	doneCh    chan struct{}
	closeOnce sync.Once
}

// standAck is one standalone channel acknowledgement handed to the
// background sender.
type standAck struct {
	ch   uint16
	next uint32
}

// NewMux wraps rel in a multiplexing session. Write state in
// cfg.StateDir is consulted when present: a fresh directory starts
// every channel at sequence 0, while a directory left by a crashed or
// restarted process resumes from the earliest confirmed per-channel
// positions held by its checkpoints and journal.
//
// A truncated journal or a flipped bit in a complete record fails
// recovery with ErrChecksum rather than replaying unverified frames.
func NewMux(rel *ReliableSession, cfg MuxConfig) (*Mux, error) {
	if cfg.Channels <= 0 {
		return nil, errors.New("codec: mux channel count must be positive")
	}
	if cfg.Window <= 0 {
		return nil, errors.New("codec: mux window must be positive")
	}
	if cfg.StateDir == "" {
		return nil, errors.New("codec: mux session requires a state directory")
	}
	if err := os.MkdirAll(cfg.StateDir, 0o755); err != nil {
		return nil, err
	}

	m := &Mux{
		rel: rel,
		cfg: cfg,
		sc:  make([]sendChannel, cfg.Channels),
		// At most Channels*Window deliveries (one per in-flight frame)
		// can be awaiting an ack send at once, so the queue is bounded by
		// the same total buffer bound and a progress-bearing signal is
		// never dropped; duplicate arrivals beyond it are coalesced
		// away because acks are cumulative.
		bases:   make([]uint32, cfg.Channels),
		seen:    make(map[muxSeq]inboundFrame),
		held:    make(map[muxSeq]inboundFrame),
		finEOF:  make([]bool, cfg.Channels),
		standCh: make(chan standAck, cfg.Channels*cfg.Window),
		stopCh:  make(chan struct{}),
		doneCh:  make(chan struct{}),
	}

	// Load the strict shared journal first, then reconcile per-channel
	// positions against the checkpoints.
	var err error
	m.log, err = openMuxLog(cfg.StateDir)
	if err != nil {
		return nil, err
	}

	// Per-channel bookkeeping derived strictly from the journal: lowest
	// and one-past-highest sequence, whether a FIN was seen, and strict
	// contiguity (a gap or a duplicate would mean a skipped or doubled
	// frame, which recovery must never silently replay).
	type span struct {
		min, max uint32
		have     bool
		fin      bool
	}
	spans := make([]span, cfg.Channels)
	for _, rec := range m.log.recs {
		if int(rec.ch) >= cfg.Channels {
			return nil, fmt.Errorf("codec: mux journal carries channel %d beyond %d: %w",
				rec.ch, cfg.Channels-1, ErrChecksum)
		}
		sp := &spans[rec.ch]
		if sp.have {
			if rec.seq != sp.max+1 {
				return nil, fmt.Errorf(
					"codec: mux journal ch %d not contiguous (seq %d after %d): %w",
					rec.ch, rec.seq, sp.max, ErrChecksum)
			}
			if sp.fin {
				return nil, fmt.Errorf(
					"codec: mux journal ch %d has frame seq %d after FIN: %w",
					rec.ch, rec.seq, ErrChecksum)
			}
		}
		if !sp.have {
			sp.min, sp.have = rec.seq, true
		}
		sp.max = rec.seq
		if rec.fin {
			sp.fin = true
		}
	}

	for ch := 0; ch < cfg.Channels; ch++ {
		cpAck, err := loadMuxCheckpoint(cfg.StateDir, uint16(ch))
		if err != nil {
			return nil, err
		}
		c := &m.sc[ch]
		sp := spans[ch]
		switch {
		case !sp.have:
			// Nothing left to replay: resume numbering at the confirmed
			// position; earlier sequences already reached the peer.
			c.acked, c.next = cpAck, cpAck
		case cpAck >= sp.max+1:
			// Checkpoint at/beyond the journal tail.
			c.acked, c.next = cpAck, cpAck
		default:
			// The journal reaches further back than the checkpoint (a
			// crash between checkpoint and prefix). Resume at the
			// EARLIER position: the overlap is resent and the receiver
			// deduplicates it; starting later would skip an
			// unacknowledged frame.
			c.acked, c.next = sp.min, sp.max+1
		}
		// A FIN record closes the channel; even after its prefix was
		// discarded the durable close marker keeps it closed.
		closedByMarker, err := muxChannelClosed(cfg.StateDir, uint16(ch))
		if err != nil {
			return nil, err
		}
		if sp.have {
			c.open = true
			c.closed = sp.fin || closedByMarker
		} else if closedByMarker {
			c.open = true
			c.closed = true
		}
	}

	// The send queue is the journal in arrival order, minus frames
	// already at/behind their channel's resumed position; it feeds
	// round-robin Flush and bounds in-flight accounting.
	m.queue = make([]*queuedFrame, 0, len(m.log.recs))
	for i := range m.log.recs {
		rec := m.log.recs[i]
		if rec.seq < m.sc[rec.ch].acked {
			continue
		}
		qf := rec.frame()
		m.queue = append(m.queue, &qf)
	}

	go m.pumpAck()
	return m, nil
}

// WriteFrame enqueues f on channel f.Channel and assigns it that
// channel's next sequence; nothing reaches the wire before Flush.
//
// It returns ErrTooLarge for a payload larger than MuxMaxPayload, the
// established checksum value for a channel number outside the session,
// ErrWindowFull when the channel already holds Window unacknowledged
// frames, and ErrChannelClosed when the channel's write side has been
// closed. A rejected frame is neither queued nor journaled and consumes
// no sequence.
func (m *Mux) WriteFrame(f ChannelFrame) error {
	if len(f.Payload) > MuxMaxPayload {
		return ErrTooLarge
	}
	if int(f.Channel) >= m.cfg.Channels {
		return fmt.Errorf("codec: mux channel %d out of range [0,%d): %w",
			f.Channel, m.cfg.Channels, ErrChecksum)
	}

	m.mu.Lock()
	defer m.mu.Unlock()

	c := &m.sc[f.Channel]
	if c.closed {
		return ErrChannelClosed
	}
	if c.next-c.acked >= uint32(m.cfg.Window) {
		return ErrWindowFull
	}

	qf := queuedFrame{
		channel: f.Channel,
		seq:     c.next,
		flags:   f.Flags,
		kind:    f.Kind,
		payload: append([]byte(nil), f.Payload...),
	}
	if err := m.log.append(qf); err != nil {
		return err
	}
	c.open = true
	c.next++
	m.queue = append(m.queue, &qf)
	return nil
}

// CloseChannel closes the write side of ch. The FIN is itself a framed
// sequence entry: it consumes one in-flight slot, so a full quota makes
// CloseChannel return ErrWindowFull and the caller retries after acks
// arrive. Closing a channel that was never written opens it first, so an
// unused channel still delivers a clean io.EOF to the peer. Closing (or
// writing to) an already closed channel returns ErrChannelClosed.
func (m *Mux) CloseChannel(ch uint16) error {
	if int(ch) >= m.cfg.Channels {
		return fmt.Errorf("codec: mux channel %d out of range [0,%d): %w",
			ch, m.cfg.Channels, ErrChecksum)
	}

	m.mu.Lock()
	defer m.mu.Unlock()

	c := &m.sc[ch]
	if c.closed {
		return ErrChannelClosed
	}
	if c.next-c.acked >= uint32(m.cfg.Window) {
		return ErrWindowFull
	}

	qf := queuedFrame{channel: ch, seq: c.next, fin: true}
	if err := m.log.append(qf); err != nil {
		return err
	}
	// Durable close marker: once a FIN is acked and the journal prefix
	// that contained it is discarded, this file is the only surviving
	// proof that the channel must never reopen. Written after the FIN
	// record, so a crash between the two leaves the FIN in the journal
	// to make the channel closed on recovery instead.
	if err := markMuxChannelClosed(m.cfg.StateDir, ch); err != nil {
		return err
	}
	c.open = true
	c.closed = true
	c.next++
	m.queue = append(m.queue, &qf)
	return nil
}

// Flush sends every queued frame with transmission opportunities handed
// out round-robin across channels: starting where the previous Flush
// stopped, each pass takes at most one queued frame per channel, so a
// continuously busy channel can never starve the others and frames
// never overtake an earlier frame of their own channel. Every data
// frame piggybacks the sender's current receive position for its
// channel; standalone acks for every channel follow the run.
//
// After a restart the queue was reloaded from the journal, so Flush is
// also the retransmit operation; the receiver deduplicates overlaps.
func (m *Mux) Flush() error {
	// Snapshot receive positions BEFORE taking the send lock: the read
	// path takes mu while applying acks (rmu-then-mu order), so mu must
	// never be held while taking rmu.
	m.rmu.Lock()
	acks := make([]uint32, m.cfg.Channels)
	copy(acks, m.bases)
	m.rmu.Unlock()

	m.mu.Lock()
	out := m.buildFlushLocked(acks)
	m.mu.Unlock()

	// Hand the planned run to the reliable session in round-robin
	// order. Its own window can fill (a restart backlog wider than one
	// window, or a slow peer): that is backpressure, not an error. Stop
	// there, flush the accepted prefix and leave every unhanded frame
	// queued for the next Flush; the receiver deduplicates the overlap.
	lastServed := -1
	for i := range out {
		err := m.rel.WriteFrame(out[i])
		if errors.Is(err, ErrWindowFull) {
			break
		}
		if err != nil {
			return err
		}
		// out is one data frame per queued entry; recover its channel
		// from its mux header rather than re-planning.
		lastServed = int(binary.BigEndian.Uint16(out[i].Payload[mhChanOff:mhSeqOff]))
	}
	if err := m.rel.Flush(); err != nil {
		return err
	}

	// Advance the round-robin cursor only past channels that actually
	// got a frame onto the wire this Flush, and only after the lower
	// flush succeeded: a failed Flush retries from the same channel.
	if lastServed >= 0 {
		m.mu.Lock()
		m.rr = (lastServed + 1) % m.cfg.Channels
		m.mu.Unlock()
	}
	return nil
}

// buildFlushLocked returns the data frames of one Flush in wire order.
// It never mutates the queue or the round-robin cursor. The caller
// holds mu.
func (m *Mux) buildFlushLocked(acks []uint32) []ReliableFrame {
	// Entries of one channel are always in ascending seq order (append
	// order at write time, journal order after a restart); pending just
	// tracks which have been taken during this Flush.
	pending := make([]*queuedFrame, len(m.queue))
	copy(pending, m.queue)

	out := make([]ReliableFrame, 0, len(pending))
	cursor := m.rr
	for len(pending) > 0 {
		startCh := cursor
		taken := false
		for step := 0; step < m.cfg.Channels; step++ {
			ch := uint16((startCh + step) % m.cfg.Channels)
			// The peer accepts exactly this channel's next Window
			// sequences; frames past the reach wait for an ack, so a
			// restart backlog wider than one window drains gradually
			// instead of being refused as "too far ahead".
			reach := m.sc[ch].acked + uint32(m.cfg.Window)
			idx := -1
			for i, qf := range pending {
				if qf.channel != ch {
					continue
				}
				if qf.seq >= reach {
					break // per-channel entries are ascending
				}
				idx = i
				break
			}
			if idx < 0 {
				continue
			}
			qf := pending[idx]
			pending = append(pending[:idx], pending[idx+1:]...)
			flag := uint8(0)
			if qf.fin {
				flag = mhFlagFin
			}
			out = append(out, ReliableFrame{
				Flags:   qf.flags,
				Kind:    qf.kind,
				Payload: encodeMuxHeader(qf.channel, qf.seq, flag, acks[qf.channel], qf.payload),
			})
			taken = true
			cursor = int(ch) + 1 // next pass starts after the served channel
		}
		if !taken {
			break
		}
	}
	return out
}

// ReadFrame returns the next deliverable frame across all channels.
// Channels are scanned independently: a channel parked waiting for a
// gap is skipped, so it never stalls another channel. Within a channel
// frames arrive in write order exactly once; out-of-order frames are
// parked until their gap closes.
//
// When a channel's FIN is reached - after every earlier frame of that
// channel was delivered - the call returns io.EOF together with a
// ChannelFrame whose Channel names the closed channel; reads on other
// channels continue unaffected.
//
// The following are refused with the established ErrChecksum and stop
// delivery stickily at the current positions: a channel number outside
// the session's reach, a residual frame older than one channel-window,
// a frame more than one channel-window ahead, an acknowledgement past
// the send frontier, a same-sequence retransmission with different
// content, an unknown flag, an ack frame carrying payload, and a
// damaged mux header. Reliable-layer results (the transport's io.EOF,
// ErrShortFrame, outer checksum/version/size and reader errors) pass
// through unchanged, and complete frames already buffered are delivered
// before a terminal lower-layer result is surfaced.
func (m *Mux) ReadFrame() (ChannelFrame, error) {
	for {
		m.rmu.Lock()
		if m.rerr != nil {
			err := m.rerr
			m.rmu.Unlock()
			return ChannelFrame{}, err
		}
		if cf, eof, ok := m.nextDeliverableLocked(); ok {
			m.rmu.Unlock()
			if eof {
				return cf, io.EOF
			}
			return cf, nil
		}
		m.rmu.Unlock()

		// Block in the reliable reader WITHOUT holding rmu, exactly like
		// the layer below: sends and ack processing must keep moving
		// while this waits for bytes.
		outer, rerr := m.rel.ReadFrame()

		m.rmu.Lock()
		if m.rerr != nil {
			err := m.rerr
			m.rmu.Unlock()
			return ChannelFrame{}, err
		}
		if rerr != nil {
			// The lower layer hands over its terminal result together
			// with any bytes that arrived in the same read; complete
			// frames already parsed below are parked in held. Deliver
			// every buffered frame across all channels first, and only
			// surface the terminal result once the buffer is drained;
			// the result is sticky and returns again on later calls.
			if cf, eof, ok := m.nextDeliverableLocked(); ok {
				m.rmu.Unlock()
				if eof {
					return cf, io.EOF
				}
				return cf, nil
			}
			return m.failReadLocked(rerr)
		}

		ch, seq, flag, ack, payload, err := decodeMuxHeader(outer.Payload)
		if err != nil {
			return m.failReadLocked(err)
		}
		if int(ch) >= m.cfg.Channels {
			return m.failReadLocked(fmt.Errorf(
				"codec: mux channel %d out of range [0,%d): %w",
				ch, m.cfg.Channels, ErrChecksum))
		}
		if flag&^uint8(mhFlagFin|mhFlagAck) != 0 {
			return m.failReadLocked(fmt.Errorf(
				"codec: mux ch %d seq %d unknown flags %#x: %w",
				ch, seq, flag, ErrChecksum))
		}
		isAck := flag&mhFlagAck != 0
		isFin := flag&mhFlagFin != 0
		if isAck && (isFin || seq != 0 || len(payload) != 0) {
			return m.failReadLocked(fmt.Errorf(
				"codec: mux ch %d malformed ack frame (fin=%v seq=%d payload=%d): %w",
				ch, isFin, seq, len(payload), ErrChecksum))
		}
		if isFin && len(payload) != 0 {
			return m.failReadLocked(fmt.Errorf(
				"codec: mux ch %d FIN seq %d carries %d payload bytes: %w",
				ch, seq, len(payload), ErrChecksum))
		}

		// Every inbound message states a cumulative position for its
		// channel; one past anything this side ever sent is impossible
		// in a well-behaved stream and is refused before anything is
		// parked or delivered.
		m.mu.Lock()
		overFrontier := ack > m.sc[ch].next
		frontier := m.sc[ch].next
		m.mu.Unlock()
		if overFrontier {
			return m.failReadLocked(fmt.Errorf(
				"codec: mux ch %d ack %d past send frontier %d: %w",
				ch, ack, frontier, ErrChecksum))
		}
		m.applyAck(ch, ack)

		if isAck {
			m.rmu.Unlock()
			continue
		}

		cf := ChannelFrame{Channel: ch, Flags: outer.Flags, Kind: outer.Kind, Payload: payload}
		fr := inboundFrame{cf: cf, fin: isFin}
		key := muxSeq{ch: ch, seq: seq}
		base := m.bases[ch]

		switch classify(seq, base, m.cfg.Window) {
		case seqInWindow:
			// A closed channel never carries another NEW sequence: its
			// FIN was the stream's last entry. Duplicate retransmits
			// (below the base) fall through to seqDuplicate and are
			// matched against the first delivered copy.
			if m.finEOF[ch] {
				return m.failReadLocked(fmt.Errorf(
					"codec: mux ch %d received new frame seq %d after FIN at %d: %w",
					ch, seq, base, ErrChecksum))
			}
			if prev, dup := m.held[key]; dup {
				// A retransmission of a parked frame must describe the
				// same frame. A same-sequence conflict is refused
				// instead of guessed, and delivery stops here.
				if !sameInbound(prev, fr) {
					return m.failReadLocked(fmt.Errorf(
						"codec: mux ch %d seq %d retransmission conflicts: %w",
						ch, seq, ErrChecksum))
				}
			} else if prev, seen := m.seen[key]; seen {
				// Already delivered once: any conflicting second
				// declaration of the same sequence is a protocol error.
				if !sameInbound(prev, fr) {
					return m.failReadLocked(fmt.Errorf(
						"codec: mux ch %d seq %d duplicate conflicts with delivered frame: %w",
						ch, seq, ErrChecksum))
				}
			} else {
				m.held[key] = fr
			}
			// Restate the channel's cumulative position either way so a
			// lost acknowledgement does not make the peer resend
			// forever.
			m.signalAckLocked(ch)
			m.rmu.Unlock()
			continue // deliver held[base] from the top of the loop
		case seqDuplicate:
			// Behind the base but within one window width. Compare with
			// the first copy delivered for that sequence; an
			// irreconcilable retransmission is refused.
			prev, known := m.seen[key]
			if known && !sameInbound(prev, fr) {
				return m.failReadLocked(fmt.Errorf(
					"codec: mux ch %d seq %d duplicate conflicts with delivered frame: %w",
					ch, seq, ErrChecksum))
			}
			m.signalAckLocked(ch)
			m.rmu.Unlock()
			continue
		default: // seqStale
			return m.failReadLocked(fmt.Errorf(
				"codec: mux ch %d seq %d outside window at %d (width %d): %w",
				ch, seq, base, m.cfg.Window, ErrChecksum))
		}
	}
}

// sameInbound reports whether two arrivals claiming one sequence carry
// the same frame (FIN marking, flags, kind and payload).
func sameInbound(a, b inboundFrame) bool {
	if a.fin != b.fin {
		return false
	}
	if a.fin {
		return true // FIN entries carry no caller frame
	}
	return a.cf.Flags == b.cf.Flags && a.cf.Kind == b.cf.Kind &&
		bytes.Equal(a.cf.Payload, b.cf.Payload)
}

// nextDeliverableLocked finds the lowest-numbered channel whose due
// sequence is parked (a FIN-closed channel is skipped), records the
// delivery and asks for an acknowledgement. It returns eof=true when
// the delivered entry is the channel's FIN: the caller then returns
// (ChannelFrame{Channel: ch}, io.EOF). Caller holds rmu.
func (m *Mux) nextDeliverableLocked() (cf ChannelFrame, eof bool, ok bool) {
	for ch := 0; ch < m.cfg.Channels; ch++ {
		if m.finEOF[ch] {
			continue
		}
		key := muxSeq{ch: uint16(ch), seq: m.bases[ch]}
		fr, present := m.held[key]
		if !present {
			continue
		}
		delete(m.held, key)
		m.bases[ch] = key.seq + 1

		// Remember the delivered frame for conflict checks on its
		// duplicates. Exactly one sequence falls out of the duplicate
		// span per one-step advance (the span ends one window width
		// behind the base), so the seen table stays bounded by
		// Channels*Window with an O(1) prune.
		m.seen[key] = fr
		delete(m.seen, muxSeq{ch: key.ch, seq: key.seq - uint32(m.cfg.Window)})

		m.signalAckLocked(key.ch)
		if fr.fin {
			m.finEOF[ch] = true
			return ChannelFrame{Channel: key.ch}, true, true
		}
		return fr.cf, false, true
	}
	return ChannelFrame{}, false, false
}

// applyAck advances one channel's cumulative send position, releases
// the freed quota slots and discards the journal prefix once the new
// position is durable. Positions that do not move the channel forward
// are ignored. The caller holds rmu (rmu-then-mu order).
func (m *Mux) applyAck(ch uint16, ack uint32) {
	m.mu.Lock()
	defer m.mu.Unlock()

	c := &m.sc[ch]
	if ack <= c.acked || ack > c.next {
		return
	}

	kept := m.queue[:0]
	for _, qf := range m.queue {
		if qf.channel == ch && qf.seq < ack {
			continue
		}
		kept = append(kept, qf)
	}
	m.queue = kept
	c.acked = ack

	// Durable per-channel position BEFORE the journal prefix is
	// discarded: a crash between the two only leaves extra frames to
	// dedupe, never a gap.
	if err := saveMuxCheckpoint(m.cfg.StateDir, ch, ack); err == nil && m.log != nil {
		_ = m.log.prefix(m.sc)
	}
}

// signalAckLocked coalescingly asks the background sender to restate
// the channel's cumulative position. It never blocks. Caller holds rmu.
func (m *Mux) signalAckLocked(ch uint16) {
	select {
	case m.standCh <- standAck{ch: ch, next: m.bases[ch]}:
	default:
	}
}

// pumpAck serializes standalone acknowledgement writes so they happen on
// this goroutine, never on a reader's: two peers reading at once cannot
// block each other. Every wakeup drains the whole queue and sends at
// most one cumulative ack per channel stating its latest position, so a
// burst of deliveries or duplicate retransmits costs a handful of
// frames rather than one per arrival.
func (m *Mux) pumpAck() {
	defer close(m.doneCh)
	for {
		select {
		case <-m.stopCh:
			return
		case first := <-m.standCh:
			latest := map[uint16]uint32{first.ch: first.next}
			draining := true
			for draining {
				select {
				case a := <-m.standCh:
					if a.next >= latest[a.ch] {
						latest[a.ch] = a.next
					}
				default:
					draining = false
				}
			}
			// Send in channel order for deterministic wire output.
			for ch := 0; ch < m.cfg.Channels; ch++ {
				next, ok := latest[uint16(ch)]
				if !ok {
					continue
				}
				b := encodeMuxHeader(uint16(ch), 0, mhFlagAck, next, nil)
				if err := m.rel.WriteFrame(ReliableFrame{Payload: b}); err == nil {
					_ = m.rel.Flush()
				}
			}
		}
	}
}

// failReadLocked records the terminal read-side result, releases rmu and
// returns it. Every caller returns immediately after calling it.
func (m *Mux) failReadLocked(err error) (ChannelFrame, error) {
	m.rerr = err
	m.rmu.Unlock()
	return ChannelFrame{}, err
}

// Close stops the background acknowledgement sender. Fully journaled
// but unacknowledged frames remain in the mux journal for a later
// restart to resend.
func (m *Mux) Close() error {
	m.closeOnce.Do(func() { close(m.stopCh) })
	return nil
}

// ----------------------------------------------------------------------
// Mux header encoding.
// ----------------------------------------------------------------------

// encodeMuxHeader serializes one mux message into reliable payload
// bytes.
func encodeMuxHeader(ch uint16, seq uint32, flags uint8, ack uint32, payload []byte) []byte {
	out := make([]byte, MuxHeaderSize+len(payload))
	binary.BigEndian.PutUint16(out[mhChanOff:mhSeqOff], ch)
	binary.BigEndian.PutUint32(out[mhSeqOff:mhFlagOff], seq)
	out[mhFlagOff] = flags
	binary.BigEndian.PutUint32(out[mhAckOff:mhCRCOff], ack)
	copy(out[mhBodyOff:], payload)
	h := crc32.NewIEEE()
	h.Write(out[:mhCRCOff])
	h.Write(out[mhBodyOff:])
	binary.BigEndian.PutUint32(out[mhCRCOff:mhBodyOff], h.Sum32())
	return out
}

// decodeMuxHeader parses one mux message. A message too short for the
// fixed header is reported with ErrShortFrame; a damaged header or
// payload with ErrChecksum.
func decodeMuxHeader(p []byte) (ch uint16, seq uint32, flags uint8, ack uint32, payload []byte, err error) {
	if len(p) < MuxHeaderSize {
		return 0, 0, 0, 0, nil, ErrShortFrame
	}
	h := crc32.NewIEEE()
	h.Write(p[:mhCRCOff])
	h.Write(p[mhBodyOff:])
	if h.Sum32() != binary.BigEndian.Uint32(p[mhCRCOff:mhBodyOff]) {
		return 0, 0, 0, 0, nil, ErrChecksum
	}
	ch = binary.BigEndian.Uint16(p[mhChanOff:mhSeqOff])
	seq = binary.BigEndian.Uint32(p[mhSeqOff:mhFlagOff])
	flags = p[mhFlagOff]
	ack = binary.BigEndian.Uint32(p[mhAckOff:mhCRCOff])
	body := make([]byte, len(p)-MuxHeaderSize)
	copy(body, p[mhBodyOff:])
	return ch, seq, flags, ack, body, nil
}

// ----------------------------------------------------------------------
// Durable state: one dual-slot, checksummed checkpoint file per channel
// and one strict CRC'd replay journal shared by all channels.
// ----------------------------------------------------------------------

const (
	muxCheckpointPrefix = "mux"
	muxCheckpointSuffix = ".ckp"
	muxJournalName      = "mux.log"

	muxCPRecordSize = 4 + 4 + 4 // generation + ack + crc32
	muxCPSlotSize   = 2 * muxCPRecordSize

	// ch(2) + seq(4) + fin(1) + flags(2) + kind(1) + len(4) + crc(4).
	muxLogHdrSize = 18
)

// muxLogRecord is one journaled mux frame on disk.
type muxLogRecord struct {
	ch    uint16
	seq   uint32
	fin   bool
	flags uint16
	kind  uint8
	f     ChannelFrame
}

// frame rebuilds the queued frame carried by a journal record.
func (r muxLogRecord) frame() queuedFrame {
	return queuedFrame{
		channel: r.ch,
		seq:     r.seq,
		flags:   r.flags,
		kind:    r.kind,
		payload: append([]byte(nil), r.f.Payload...),
		fin:     r.fin,
	}
}

// muxLog is the append-only shared journal.
type muxLog struct {
	path string
	mu   sync.Mutex
	recs []muxLogRecord
}

func muxCheckpointPath(dir string, ch uint16) string {
	return filepath.Join(dir, fmt.Sprintf("%s%03d%s", muxCheckpointPrefix, ch, muxCheckpointSuffix))
}

// muxCloseSuffix names a channel's durable write-side close marker; the
// file's mere presence records that the FIN was durably issued.
const muxCloseSuffix = ".closed"

func muxClosePath(dir string, ch uint16) string {
	return filepath.Join(dir, fmt.Sprintf("%s%03d%s", muxCheckpointPrefix, ch, muxCloseSuffix))
}

// markMuxChannelClosed durably records that ch's write side is closed.
func markMuxChannelClosed(dir string, ch uint16) error {
	f, err := os.OpenFile(muxClosePath(dir, ch), os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
	if err != nil {
		return err
	}
	if _, err := f.Write([]byte("closed\n")); err != nil {
		f.Close()
		return err
	}
	if err := f.Sync(); err != nil {
		f.Close()
		return err
	}
	return f.Close()
}

// muxChannelClosed reports whether the durable close marker exists.
func muxChannelClosed(dir string, ch uint16) (bool, error) {
	switch _, err := os.Stat(muxClosePath(dir, ch)); {
	case err == nil:
		return true, nil
	case os.IsNotExist(err):
		return false, nil
	default:
		return false, err
	}
}

// loadMuxCheckpoint returns a channel's newest valid checkpointed
// "next expected" position. Missing state, an empty file or records
// that all fail validation mean position 0: with nothing confirmed the
// safe action is to replay what the journal holds and let the receiver
// deduplicate the overlap.
func loadMuxCheckpoint(dir string, ch uint16) (uint32, error) {
	data, err := os.ReadFile(muxCheckpointPath(dir, ch))
	if err != nil {
		if os.IsNotExist(err) {
			return 0, nil
		}
		return 0, err
	}
	var bestGen, bestAck uint32
	found := false
	for off := 0; off+muxCPRecordSize <= len(data); off += muxCPRecordSize {
		if binary.BigEndian.Uint32(data[off+8:off+12]) != crc32.ChecksumIEEE(data[off:off+8]) {
			continue
		}
		gen := binary.BigEndian.Uint32(data[off : off+4])
		ack := binary.BigEndian.Uint32(data[off+4 : off+8])
		if !found || gen > bestGen || (gen == bestGen && ack > bestAck) {
			bestGen, bestAck, found = gen, ack, true
		}
	}
	if !found {
		return 0, nil
	}
	return bestAck, nil
}

// nextMuxCPSlot chooses the slot to overwrite and the next generation:
// alternate slots, strictly increasing generations.
func nextMuxCPSlot(dir string, ch uint16) (slot int, generation uint32, err error) {
	data, rerr := os.ReadFile(muxCheckpointPath(dir, ch))
	if rerr != nil && !os.IsNotExist(rerr) {
		return 0, 0, rerr
	}
	var gens [2]uint32
	var ok [2]bool
	for i := 0; i < 2; i++ {
		lo, hi := i*muxCPRecordSize, (i+1)*muxCPRecordSize
		if len(data) >= hi &&
			binary.BigEndian.Uint32(data[lo+8:lo+12]) == crc32.ChecksumIEEE(data[lo:lo+8]) {
			gens[i], ok[i] = binary.BigEndian.Uint32(data[lo:lo+4]), true
		}
	}
	switch {
	case !ok[0] && !ok[1]:
		return 0, 1, nil
	case ok[0] && (!ok[1] || gens[0] >= gens[1]):
		return 1, gens[0] + 1, nil
	default:
		return 0, gens[1] + 1, nil
	}
}

// saveMuxCheckpoint writes one new record into the alternate slot of
// the channel's checkpoint file, leaving the other slot untouched so at
// least the previous complete record always survives.
func saveMuxCheckpoint(dir string, ch uint16, ack uint32) error {
	slot, generation, err := nextMuxCPSlot(dir, ch)
	if err != nil {
		return err
	}
	path := muxCheckpointPath(dir, ch)

	needPad := true
	if info, statErr := os.Stat(path); statErr == nil && info.Size() >= int64(muxCPSlotSize) {
		needPad = false
	}
	f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE, 0o644)
	if err != nil {
		return err
	}
	defer f.Close()
	if needPad {
		if _, err := f.WriteAt(make([]byte, muxCPSlotSize), 0); err != nil {
			return err
		}
	}
	rec := make([]byte, muxCPRecordSize)
	binary.BigEndian.PutUint32(rec[0:4], generation)
	binary.BigEndian.PutUint32(rec[4:8], ack)
	binary.BigEndian.PutUint32(rec[8:12], crc32.ChecksumIEEE(rec[0:8]))
	if _, err := f.WriteAt(rec, int64(slot*muxCPRecordSize)); err != nil {
		return err
	}
	return f.Sync()
}

// openMuxLog loads the shared journal strictly.
func openMuxLog(dir string) (*muxLog, error) {
	l := &muxLog{path: filepath.Join(dir, muxJournalName)}
	if err := l.load(); err != nil {
		return nil, err
	}
	return l, nil
}

func (l *muxLog) load() error {
	data, err := os.ReadFile(l.path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return err
	}
	for off := 0; off < len(data); {
		// Any bytes that do not form a complete, valid record are a
		// truncated tail: strict failure, no further delivery.
		if len(data)-off < muxLogHdrSize {
			return fmt.Errorf("codec: mux journal %s truncated: %w", muxJournalName, ErrChecksum)
		}
		hdr := data[off : off+muxLogHdrSize]
		ch := binary.BigEndian.Uint16(hdr[0:2])
		seq := binary.BigEndian.Uint32(hdr[2:6])
		fin := hdr[6] != 0
		if hdr[6]&^1 != 0 {
			return fmt.Errorf("codec: mux journal %s bad fin flag: %w", muxJournalName, ErrChecksum)
		}
		flags := binary.BigEndian.Uint16(hdr[7:9])
		kind := hdr[9]
		plen := int(binary.BigEndian.Uint32(hdr[10:14]))
		wantCRC := binary.BigEndian.Uint32(hdr[14:18])
		end := off + muxLogHdrSize + plen
		if plen < 0 || end > len(data) {
			return fmt.Errorf("codec: mux journal %s truncated: %w", muxJournalName, ErrChecksum)
		}
		h := crc32.NewIEEE()
		h.Write(hdr[:14])
		h.Write(data[off+muxLogHdrSize : end])
		if h.Sum32() != wantCRC {
			return fmt.Errorf("codec: mux journal %s corrupted: %w", muxJournalName, ErrChecksum)
		}
		payload := make([]byte, plen)
		copy(payload, data[off+muxLogHdrSize:end])
		l.recs = append(l.recs, muxLogRecord{
			ch: ch, seq: seq, fin: fin, flags: flags, kind: kind,
			f: ChannelFrame{Channel: ch, Flags: flags, Kind: kind, Payload: payload},
		})
		off = end
	}
	return nil
}

// append journals one accepted frame as one fully checksummed record.
func (l *muxLog) append(qf queuedFrame) error {
	l.mu.Lock()
	defer l.mu.Unlock()

	hdr := make([]byte, muxLogHdrSize)
	binary.BigEndian.PutUint16(hdr[0:2], qf.channel)
	binary.BigEndian.PutUint32(hdr[2:6], qf.seq)
	if qf.fin {
		hdr[6] = 1
	}
	binary.BigEndian.PutUint16(hdr[7:9], qf.flags)
	hdr[9] = qf.kind
	binary.BigEndian.PutUint32(hdr[10:14], uint32(len(qf.payload)))
	h := crc32.NewIEEE()
	h.Write(hdr[:14])
	h.Write(qf.payload)
	binary.BigEndian.PutUint32(hdr[14:18], h.Sum32())

	file, err := os.OpenFile(l.path, os.O_WRONLY|os.O_CREATE|os.O_APPEND, 0o644)
	if err != nil {
		return err
	}
	// One write of the whole record keeps the on-disk tail either
	// absent or complete from the point of view of a killing crash.
	if _, err := file.Write(append(hdr, qf.payload...)); err != nil {
		file.Close()
		return err
	}
	if err := file.Sync(); err != nil {
		file.Close()
		return err
	}
	if err := file.Close(); err != nil {
		return err
	}

	l.recs = append(l.recs, muxLogRecord{
		ch:    qf.channel,
		seq:   qf.seq,
		fin:   qf.fin,
		flags: qf.flags,
		kind:  qf.kind,
		f: ChannelFrame{
			Channel: qf.channel, Flags: qf.flags, Kind: qf.kind, Payload: qf.payload,
		},
	})
	return nil
}

// prefix discards every journaled frame already at or behind its
// channel's confirmed position, rewriting the journal atomically via
// temp file + rename.
func (l *muxLog) prefix(sc []sendChannel) error {
	l.mu.Lock()
	defer l.mu.Unlock()

	keep := l.recs[:0]
	for _, r := range l.recs {
		if int(r.ch) < len(sc) && r.seq < sc[r.ch].acked {
			continue
		}
		keep = append(keep, r)
	}
	if len(keep) == len(l.recs) {
		return nil
	}
	l.recs = keep

	tmp := l.path + ".tmp"
	f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
	if err != nil {
		return err
	}
	writeRec := func(r muxLogRecord) error {
		hdr := make([]byte, muxLogHdrSize)
		binary.BigEndian.PutUint16(hdr[0:2], r.ch)
		binary.BigEndian.PutUint32(hdr[2:6], r.seq)
		if r.fin {
			hdr[6] = 1
		}
		binary.BigEndian.PutUint16(hdr[7:9], r.flags)
		hdr[9] = r.kind
		binary.BigEndian.PutUint32(hdr[10:14], uint32(len(r.f.Payload)))
		h := crc32.NewIEEE()
		h.Write(hdr[:14])
		h.Write(r.f.Payload)
		binary.BigEndian.PutUint32(hdr[14:18], h.Sum32())
		if _, err := f.Write(hdr); err != nil {
			return err
		}
		_, err := f.Write(r.f.Payload)
		return err
	}
	for _, r := range keep {
		if err := writeRec(r); err != nil {
			f.Close()
			return err
		}
	}
	if err := f.Sync(); err != nil {
		f.Close()
		return err
	}
	if err := f.Close(); err != nil {
		return err
	}
	return os.Rename(tmp, l.path)
}

// Package codec implements encoding and decoding of single binary frames
// in a length-prefixed wire format.
//
// Wire layout (all multi-byte fields big-endian):
//
//	+------------+---------+--------+------+----------+=========+
//	| length (4) | ver (1) | flags(2)| kind(1)| cksum(2) | payload |
//	+------------+---------+--------+------+----------+=========+
//
// The 4-byte length counts payload bytes only. The 10-byte header is
// length + version + flags + kind + checksum. The checksum is the low
// 16 bits of the byte-wise sum of all header bytes except the checksum
// field itself, plus every payload byte.
package codec

import (
	"encoding/binary"
	"errors"
)

const (
	// Version is the only protocol version this codec reads and writes.
	Version = 1

	// HeaderSize is the total header length in bytes:
	// 4 (length) + 1 (version) + 2 (flags) + 1 (kind) + 2 (checksum).
	HeaderSize = 10

	// MaxPayload is the maximum payload size in bytes a frame may carry.
	MaxPayload = 1 << 20 // 1 MiB
)

var (
	// ErrShortFrame is returned when the input is too short to contain a
	// complete frame.
	ErrShortFrame = errors.New("codec: short frame")
	// ErrBadVersion is returned when the frame version is not supported.
	ErrBadVersion = errors.New("codec: unsupported version")
	// ErrChecksum is returned when the checksum does not match the
	// recomputed value.
	ErrChecksum = errors.New("codec: checksum mismatch")
	// ErrTooLarge is returned when the payload exceeds MaxPayload.
	ErrTooLarge = errors.New("codec: payload too large")
)

// Frame is a single decoded frame, or the input to Encode.
type Frame struct {
	Version uint8
	Flags   uint16
	Kind    uint8
	Payload []byte
}

// checksum sums every byte of header-and-payload except the checksum
// field itself and keeps the low 16 bits.
func checksum(data []byte) uint16 {
	var sum uint32
	for _, b := range data {
		sum += uint32(b)
	}
	return uint16(sum)
}

// Encode serializes f into the wire format. The version written is
// always Version. It returns ErrTooLarge if the payload exceeds
// MaxPayload.
func Encode(f Frame) ([]byte, error) {
	if len(f.Payload) > MaxPayload {
		return nil, ErrTooLarge
	}

	out := make([]byte, HeaderSize+len(f.Payload))
	binary.BigEndian.PutUint32(out[0:4], uint32(len(f.Payload)))
	out[4] = Version
	binary.BigEndian.PutUint16(out[5:7], f.Flags)
	out[7] = f.Kind
	copy(out[HeaderSize:], f.Payload)

	// Sum the header bytes before the checksum field plus the payload.
	sum := checksum(out[0:8]) + checksum(out[HeaderSize:])
	binary.BigEndian.PutUint16(out[8:10], sum)
	return out, nil
}

// Decode parses one frame from data. On any error it returns the zero
// Frame and one of ErrShortFrame, ErrBadVersion, ErrChecksum or
// ErrTooLarge; checks run in that order so the same corrupt input always
// yields the same error.
func Decode(data []byte) (Frame, error) {
	var f Frame

	// 1. Length: enough bytes for the header, then for the declared payload.
	if len(data) < HeaderSize {
		return f, ErrShortFrame
	}
	payloadLen := binary.BigEndian.Uint32(data[0:4])
	if uint64(len(data)) < uint64(HeaderSize)+uint64(payloadLen) {
		return f, ErrShortFrame
	}

	// 2. Version.
	version := data[4]
	if version != Version {
		return f, ErrBadVersion
	}

	// 3. Checksum over header (minus the checksum field) and payload.
	want := binary.BigEndian.Uint16(data[8:10])
	got := checksum(data[0:8]) + checksum(data[HeaderSize:HeaderSize+int(payloadLen)])
	if got != want {
		return f, ErrChecksum
	}

	// 4. Size.
	if payloadLen > MaxPayload {
		return f, ErrTooLarge
	}

	payload := make([]byte, payloadLen)
	copy(payload, data[HeaderSize:HeaderSize+int(payloadLen)])

	f.Version = version
	f.Flags = binary.BigEndian.Uint16(data[5:7])
	f.Kind = data[7]
	f.Payload = payload
	return f, nil
}

package codec

import (
	"encoding/binary"
	"errors"
	"fmt"
	"hash/crc32"
	"os"
	"path/filepath"
	"sync"
	"sync/atomic"
)

// Reliable transport on top of the multi-frame Session.
//
// This layer adds sequence numbers, cumulative acknowledgements and a
// sliding-window pipeline. It does not touch the wire encoding of the
// layer below: every reliable message is carried inside the Payload of
// one ordinary codec frame, prefixed by this layer's own envelope. The
// Encode/Decode entries, the header constants and the four existing
// error values keep their exact byte-level semantics.
//
// Envelope layout inside a codec frame payload (all multi-byte fields
// big-endian):
//
//		+---------+---------+--------+----------+---------+----------+=========+
//		| seq (4) | ack (4) | type(1)| flags(2) | kind(1) | crc32(4) | payload |
//		+---------+---------+--------+----------+---------+----------+=========+
//
//	  - seq: sender-assigned data sequence; ACK frames carry no data seq.
//	  - ack: cumulative acknowledgement as a "next expected" count: every
//	    data frame with seq < ack has been delivered to the reader.
//	  - type: 1 = data, 2 = pure acknowledgement.
//	  - flags/kind: the caller frame's Flags and Kind, carried inside the
//	    envelope; the outer codec Kind is a fixed marker of this layer.
//	  - crc32: IEEE CRC of the other 12 envelope bytes plus the payload.
//
// The underlying frame's payload limit stays MaxPayload; EnvelopeSize
// bytes are reserved, so the inner payload limit is ReliableMaxPayload.
//
// Delivery guarantees, across disconnects and sender-side restarts:
//   - Write side: frames are numbered in write order and streamed
//     through a fixed send window. Written frames are journaled in a
//     CRC'd replay log; the acknowledged position is recorded in a
//     dual-slot checkpoint. After a restart, sending resumes after the
//     earliest confirmed position recorded by either file, so an
//     acknowledged frame is never counted twice and no frame past it is
//     skipped (a resupplied frame is deduped on arrival).
//   - Read side: frames are delivered in sequence order exactly once.
//     A duplicate of an already delivered or already held frame is
//     acknowledged again but delivered once; an in-order gap closed by
//     an out-of-order arrival flushes the held run in order; a sequence
//     older than the window's duplicate span or more than one window
//     width ahead is refused and delivery stops at the current
//     position.
const (
	// EnvelopeSize is this layer's per-frame overhead:
	// 4 (seq) + 4 (ack) + 1 (type) + 2 (flags) + 1 (kind) + 4 (crc32).
	EnvelopeSize = 16

	// ReliableMaxPayload is the largest inner payload a reliable data
	// frame may carry; EnvelopeSize bytes are reserved inside the
	// underlying frame, whose own limit stays MaxPayload.
	ReliableMaxPayload = MaxPayload - EnvelopeSize

	// envelope field offsets.
	envSeqOff   = 0
	envAckOff   = 4
	envTypeOff  = 8
	envFlagsOff = 9
	envKindOff  = 11
	envCRCOff   = 12
	envBodyOff  = 16
)

const (
	envTypeData = 1
	envTypeAck  = 2

	// outerKind is the codec-frame Kind of every reliable message; the
	// caller's Kind travels inside the envelope and is never confused
	// with this marker.
	outerKind uint8 = 0xA5
)

// ErrWindowFull is the established over-limit value a write returns when
// the send window already holds the maximum number of unacknowledged
// frames. It is the same sentinel the single-frame encoder uses for an
// over-limit payload: an over-window write is an over-limit write, and
// the offered frame is dropped without entering the window or the log
// and without consuming a sequence number.
var ErrWindowFull = ErrTooLarge

// ReliableFrame is one caller-visible frame on the reliable layer.
type ReliableFrame struct {
	Flags   uint16
	Kind    uint8
	Payload []byte
}

// envelope is one parsed reliable message.
type envelope struct {
	seq     uint32
	ack     uint32
	typ     uint8
	flags   uint16
	kind    uint8
	payload []byte
}

// encodeEnvelope serializes one message into the payload bytes of an
// ordinary codec frame.
func encodeEnvelope(e envelope) ([]byte, error) {
	if e.typ == envTypeData && len(e.payload) > ReliableMaxPayload {
		return nil, ErrTooLarge
	}
	out := make([]byte, EnvelopeSize+len(e.payload))
	binary.BigEndian.PutUint32(out[envSeqOff:envSeqOff+4], e.seq)
	binary.BigEndian.PutUint32(out[envAckOff:envAckOff+4], e.ack)
	out[envTypeOff] = e.typ
	binary.BigEndian.PutUint16(out[envFlagsOff:envFlagsOff+2], e.flags)
	out[envKindOff] = e.kind
	copy(out[envBodyOff:], e.payload)
	h := crc32.NewIEEE()
	h.Write(out[:envCRCOff])
	h.Write(out[envBodyOff:])
	binary.BigEndian.PutUint32(out[envCRCOff:envCRCOff+4], h.Sum32())
	return out, nil
}

// decodeEnvelope parses one message from a codec frame payload. A
// damaged envelope is reported with the established checksum value;
// nothing is delivered from it.
func decodeEnvelope(p []byte) (envelope, error) {
	var e envelope
	if len(p) < EnvelopeSize {
		return e, ErrShortFrame
	}
	h := crc32.NewIEEE()
	h.Write(p[:envCRCOff])
	h.Write(p[envBodyOff:])
	if h.Sum32() != binary.BigEndian.Uint32(p[envCRCOff:envCRCOff+4]) {
		return e, ErrChecksum
	}
	e.seq = binary.BigEndian.Uint32(p[envSeqOff : envSeqOff+4])
	e.ack = binary.BigEndian.Uint32(p[envAckOff : envAckOff+4])
	e.typ = p[envTypeOff]
	e.flags = binary.BigEndian.Uint16(p[envFlagsOff : envFlagsOff+2])
	e.kind = p[envKindOff]
	body := make([]byte, len(p)-EnvelopeSize)
	copy(body, p[EnvelopeSize:])
	e.payload = body
	return e, nil
}

// ReliableConfig configures a ReliableSession.
type ReliableConfig struct {
	// Window is the send and receive window width in frames. It must be
	// positive. Both peers of one connection should use the same width.
	Window int

	// StateDir holds the checkpoint file and replay log used to resume
	// the write side after a restart. It is created if missing.
	StateDir string
}

// ReliableSession is a reliability layer wrapping one Session. Create it
// with NewReliable; the wrapped session must not be used directly while
// the ReliableSession owns it.
//
// The two directions are independent and may be used concurrently, like
// the underlying session. A writer that wants the peer's
// acknowledgements to advance its window must let ReadFrame run
// (acknowledgements are consumed there, in a dedicated goroutine when
// traffic is one-directional).
type ReliableSession struct {
	sess *Session
	cfg  ReliableConfig

	wmu sync.Mutex
	// sendBase is the oldest sequence not yet acknowledged (as a
	// next-expected ack value); sendNext is the next sequence a newly
	// written frame gets. Slot i holds sequence sendBase+i while it is
	// unacknowledged.
	sendBase uint32
	sendNext uint32
	window   []windowSlot
	log      *replayLog
	closed   bool

	rmu sync.Mutex
	// recvBase is the next sequence due for delivery. It is atomic so the
	// send paths (Flush, the ack pump) can read the position without
	// taking rmu: ReadFrame must keep rmu free while blocked in the
	// underlying reader, otherwise two peers reading at once deadlock.
	recvBase atomic.Uint32
	// held parks frames that arrived in-window but ahead of order; it is
	// guarded by rmu.
	held map[uint32]ReliableFrame
	rerr error

	// ackCh is a coalescing signal: every delivery that moves recvBase
	// (or repeats a duplicate the sender is still resending) pokes it
	// non-blockingly, and pumpAck flushes one cumulative acknowledgement
	// for the latest position. A capacity of 1 is enough because acks
	// are cumulative. Keeping the write off the read path means two
	// peers reading at the same time cannot block each other.
	ackCh  chan struct{}
	stopCh chan struct{}
	doneCh chan struct{}
}

type windowSlot struct {
	used bool
	seq  uint32
	f    ReliableFrame
}

// NewReliable wraps sess in a reliable session. Write state in
// cfg.StateDir is consulted when present: a fresh directory starts at
// sequence 0, while a directory left by a crashed or restarted process
// resumes from the earliest confirmed position held by its checkpoint
// and replay log.
//
// A checkpoint record torn by a crash mid-write fails its own checksum
// and is ignored in favor of the previous complete record. A replayed
// log that is truncated or contains a flipped bit fails with
// ErrChecksum.
func NewReliable(sess *Session, cfg ReliableConfig) (*ReliableSession, error) {
	if cfg.Window <= 0 {
		return nil, errors.New("codec: reliable window must be positive")
	}
	if cfg.StateDir == "" {
		return nil, errors.New("codec: reliable session requires a state directory")
	}
	if err := os.MkdirAll(cfg.StateDir, 0o755); err != nil {
		return nil, err
	}

	rs := &ReliableSession{
		sess:   sess,
		cfg:    cfg,
		window: make([]windowSlot, cfg.Window),
		held:   make(map[uint32]ReliableFrame),
		ackCh:  make(chan struct{}, 1),
		stopCh: make(chan struct{}),
		doneCh: make(chan struct{}),
	}

	// Newest valid checkpoint record; a torn record is invisible here.
	cpAck, _, err := loadCheckpoint(cfg.StateDir)
	if err != nil {
		return nil, err
	}

	rs.log, err = openReplayLog(cfg.StateDir)
	if err != nil {
		return nil, err
	}

	logBase, logNext, logEmpty := rs.log.bounds()
	switch {
	case logEmpty || cpAck >= logNext:
		// Either there is nothing left to replay, or the checkpoint
		// confirms a position at/beyond the log's tail (the journaled
		// records are all older, already-delivered frames). Resume at the
		// checkpoint: numbering new frames any earlier would collide with
		// sequences the peer already received.
		rs.sendBase = cpAck
		rs.sendNext = cpAck
	default:
		// Log tail extends past the checkpoint. Resume at the log's
		// first replayable frame. A checkpoint is durably written BEFORE
		// its log prefix is discarded, so a crash can leave a log that
		// still reaches further back than the checkpoint; resending that
		// overlap is safe because the receiver deduplicates it. Starting
		// any later would skip a frame that was never confirmed; starting
		// earlier than logBase is impossible because those frames were
		// already discarded by a confirmed checkpoint.
		rs.sendBase = logBase
		// sendNext stays one past the last journaled frame. A replay
		// backlog wider than the window drains as acks advance and the
		// freed tail slots are refilled from the log.
		rs.sendNext = logNext
	}

	rs.reloadWindow()
	// Start the ack pump only after every error-return path is past: on
	// a failed NewReliable no session (and no pump goroutine) exists.
	go rs.pumpAck()
	return rs, nil
}

// reloadWindow refills the in-memory window slots from the replay log
// after a restart, so the first Flush resends every frame past the
// resume point.
func (rs *ReliableSession) reloadWindow() {
	for i := range rs.window {
		rs.window[i] = windowSlot{}
	}
	for _, rec := range rs.log.framesFrom(rs.sendBase) {
		idx := int(rec.seq - rs.sendBase)
		if idx >= len(rs.window) {
			break
		}
		rs.window[idx] = windowSlot{used: true, seq: rec.seq, f: rec.f}
	}
}

// WriteFrame numbers f with the next send sequence, journals it and
// parks it in the send window. Nothing is transmitted before Flush.
// When the window already holds Window unacknowledged frames, WriteFrame
// returns ErrWindowFull (the established over-limit value) and drops the
// frame: it is neither windowed nor journaled and consumes no sequence.
// An oversized inner payload returns ErrTooLarge before anything else.
func (rs *ReliableSession) WriteFrame(f ReliableFrame) error {
	if len(f.Payload) > ReliableMaxPayload {
		return ErrTooLarge
	}
	rs.wmu.Lock()
	defer rs.wmu.Unlock()

	if rs.closed {
		return errors.New("codec: write on closed reliable session")
	}
	if rs.sendNext-rs.sendBase >= uint32(rs.cfg.Window) {
		return ErrWindowFull
	}

	seq := rs.sendNext
	if err := rs.log.append(seq, f); err != nil {
		return err
	}
	rs.window[int(seq-rs.sendBase)] = windowSlot{used: true, seq: seq, f: f}
	rs.sendNext++
	return nil
}

// Flush sends every windowed frame in sequence order, each carrying the
// read side's current delivered position as a cumulative ack, followed
// by one pure acknowledgement, and flushes the wrapped session.
//
// Retransmission is a plain Flush on a restarted writer: the window was
// reloaded from the replay log, so Flush resends every frame past the
// resume point; the reader delivers each at most once.
func (rs *ReliableSession) Flush() error {
	// recvBase is atomic, so no read lock is taken here: Flush never
	// blocks a concurrent ReadFrame and vice versa.
	ack := rs.recvBase.Load()

	rs.wmu.Lock()
	out := make([]Frame, 0, len(rs.window)+1)
	for i := range rs.window {
		sl := &rs.window[i]
		if !sl.used {
			continue
		}
		b, err := encodeEnvelope(envelope{
			seq:     sl.seq,
			ack:     ack,
			typ:     envTypeData,
			flags:   sl.f.Flags,
			kind:    sl.f.Kind,
			payload: sl.f.Payload,
		})
		if err != nil {
			rs.wmu.Unlock()
			return err
		}
		out = append(out, Frame{Kind: outerKind, Payload: b})
	}
	out = append(out, rs.ackFrameLocked(ack))
	rs.wmu.Unlock()

	for i := range out {
		if err := rs.sess.WriteFrame(out[i]); err != nil {
			return err
		}
	}
	return rs.sess.Flush()
}

// ackFrameLocked builds a pure acknowledgement. Caller holds wmu; the
// envelope's own seq is zero because ACK frames carry no data sequence.
func (rs *ReliableSession) ackFrameLocked(ack uint32) Frame {
	b, _ := encodeEnvelope(envelope{ack: ack, typ: envTypeAck})
	return Frame{Kind: outerKind, Payload: b}
}

// ReadFrame returns the next in-order caller frame, exactly once. It
// internally processes reliable messages: acknowledgements (pure ones
// and piggybacked ones) advance the send window, duplicates are
// re-acknowledged but not redelivered, and in-window out-of-order frames
// are held until the gap closes and then delivered as a contiguous run.
// A sequence outside the window's reach - a residual older than the
// duplicate span or a declared sequence more than one window width
// ahead - is refused with ErrChecksum and delivery stops at the last
// in-order frame; the refusal is sticky.
func (rs *ReliableSession) ReadFrame() (ReliableFrame, error) {
	for {
		rs.rmu.Lock()
		if rs.rerr != nil {
			err := rs.rerr
			rs.rmu.Unlock()
			return ReliableFrame{}, err
		}
		// A contiguous held frame can be delivered without another read.
		if f, ok := rs.held[rs.recvBase.Load()]; ok {
			base := rs.recvBase.Load()
			delete(rs.held, base)
			rs.recvBase.Store(base + 1)
			rs.signalAck()
			rs.rmu.Unlock()
			return f, nil
		}
		rs.rmu.Unlock()

		// Block in the underlying reader WITHOUT holding rmu: the read
		// may wait indefinitely for bytes, and the send paths must stay
		// able to observe recvBase meanwhile. The wrapped session
		// serializes concurrent readers, so each wakeup owns one frame.
		outer, rerr := rs.sess.ReadFrame()

		rs.rmu.Lock()
		// Another reader may have recorded a terminal result while this
		// one was blocked in the underlying read.
		if rs.rerr != nil {
			err := rs.rerr
			rs.rmu.Unlock()
			return ReliableFrame{}, err
		}
		if rerr != nil {
			// Outer-layer results (io.EOF, a corrupt outer frame, a
			// truncated trailing frame, an underlying reader error) pass
			// through with their established values.
			return rs.failReadLocked(rerr)
		}

		env, err := decodeEnvelope(outer.Payload)
		if err != nil {
			return rs.failReadLocked(err)
		}

		// Every inbound message may carry a cumulative acknowledgement
		// for data we sent.
		rs.applyAck(env.ack)

		if env.typ == envTypeAck {
			rs.rmu.Unlock()
			continue
		}
		if env.typ != envTypeData {
			// An unknown message type cannot be placed in the ordered
			// stream; refuse it like a damaged envelope.
			return rs.failReadLocked(fmt.Errorf("codec: unknown reliable message type %d: %w", env.typ, ErrChecksum))
		}

		rf := ReliableFrame{Flags: env.flags, Kind: env.kind, Payload: env.payload}
		base := rs.recvBase.Load()

		switch classify(env.seq, base, rs.cfg.Window) {
		case seqInWindow:
			if _, dup := rs.held[env.seq]; !dup {
				// First arrival: park it. A retransmission of the same
				// parked frame keeps the first copy.
				rs.held[env.seq] = rf
			}
			// Restate the cumulative position either way (a fresh frame
			// extends it only after in-order delivery; the duplicate case
			// needs it so the peer stops resending).
			rs.signalAck()
			rs.rmu.Unlock()
			continue // deliver held[recvBase] from the top of the loop
		case seqDuplicate:
			// Already delivered in an earlier call - a resend after its
			// acknowledgement was lost. Do not deliver again; restate the
			// cumulative position.
			rs.signalAck()
			rs.rmu.Unlock()
			continue
		case seqStale:
			// Older than the duplicate span, or more than a window width
			// ahead: refuse and stop where delivery currently is.
			return rs.failReadLocked(fmt.Errorf("codec: sequence %d outside window at %d (width %d): %w",
				env.seq, base, rs.cfg.Window, ErrChecksum))
		}
	}
}

type seqClass int

const (
	seqDuplicate seqClass = iota // behind base, within one window width
	seqInWindow                  // [base, base+Window)
	seqStale                     // anywhere else: ancient residual or too far ahead
)

// classify positions an inbound sequence relative to a receive window
// starting at base. uint32 modular subtraction keeps the check correct
// across sequence wraparound.
func classify(seq, base uint32, window int) seqClass {
	if fwd := seq - base; fwd < uint32(window) {
		return seqInWindow
	}
	if back := base - seq; back >= 1 && back <= uint32(window) {
		return seqDuplicate
	}
	return seqStale
}

// signalAck coalescingly asks the ack pump to restate recvBase. It never
// blocks and never writes from under the read lock.
func (rs *ReliableSession) signalAck() {
	select {
	case rs.ackCh <- struct{}{}:
	default:
	}
}

// pumpAck serializes all standalone acknowledgement writes. One poke
// yields at most one ack stating the latest delivered position, so a
// burst of deliveries sends a few cumulative acks rather than one per
// frame. Writes happen on this goroutine, not on the caller's read
// goroutine, which is what lets two peers read simultaneously without
// deadlocking.
func (rs *ReliableSession) pumpAck() {
	defer close(rs.doneCh)
	for {
		select {
		case <-rs.stopCh:
			return
		case <-rs.ackCh:
		}

		// Coalesce pokes that accumulated while the previous ack was
		// being written.
		select {
		case <-rs.ackCh:
		default:
		}

		ack := rs.recvBase.Load()
		rs.wmu.Lock()
		frame := rs.ackFrameLocked(ack)
		rs.wmu.Unlock()
		// Best effort: a failed or blocked ack is harmless because every
		// later Flush piggybacks the same cumulative position.
		if err := rs.sess.WriteFrame(frame); err == nil {
			_ = rs.sess.Flush()
		}
	}
}

// applyAck advances the send window past a cumulative "next expected"
// acknowledgement and makes the new position durable. Called with rmu
// held; takes wmu (rmu-then-wmu order).
func (rs *ReliableSession) applyAck(ack uint32) {
	rs.wmu.Lock()
	defer rs.wmu.Unlock()

	// ack states that every seq < ack is delivered. Ignore values that
	// do not move the window forward or pass the highest numbered seq.
	if ack <= rs.sendBase || ack > rs.sendNext {
		return
	}
	shift := ack - rs.sendBase
	if shift > uint32(len(rs.window)) {
		shift = uint32(len(rs.window))
	}

	// Slide occupied slots down; sources are always read at higher
	// indices than the destination, so overlap cannot erase an unread
	// slot.
	for i := 0; i+int(shift) < len(rs.window); i++ {
		rs.window[i] = rs.window[i+int(shift)]
	}
	for i := len(rs.window) - int(shift); i < len(rs.window); i++ {
		rs.window[i] = windowSlot{}
	}
	rs.sendBase += shift

	// After a restart the replay backlog may be wider than the window:
	// the freed tail slots are refilled from the log as the window
	// advances, so every journaled frame eventually goes out.
	rs.reloadWindow()

	// Make the new position durable BEFORE discarding the journaled
	// prefix: a crash between the two leaves extra replayable frames
	// (deduped on resend), never a gap. Prefix only after the checkpoint
	// actually landed: a failed checkpoint plus a successful prefix would
	// otherwise be the one ordering that can lose frames.
	if err := saveCheckpoint(rs.cfg.StateDir, rs.sendBase); err == nil && rs.log != nil {
		_ = rs.log.prefix(rs.sendBase)
	}
}

// failReadLocked records the terminal read-side result, releases rmu and
// returns it. Every caller returns immediately after calling it.
func (rs *ReliableSession) failReadLocked(err error) (ReliableFrame, error) {
	rs.rerr = err
	rs.rmu.Unlock()
	return ReliableFrame{}, err
}

// Close marks the session closed and asks the acknowledgement pump to
// stop; a pump blocked on an unread transport unwinds once that
// transport is closed. Fully journaled but unacknowledged frames remain
// in the replay log for a later restart to resend.
func (rs *ReliableSession) Close() error {
	rs.wmu.Lock()
	if rs.closed {
		rs.wmu.Unlock()
		return nil
	}
	rs.closed = true
	rs.wmu.Unlock()
	close(rs.stopCh)
	return nil
}

// ----------------------------------------------------------------------
// Durable state: a dual-slot, checksummed checkpoint and a strict,
// CRC'd replay log.
// ----------------------------------------------------------------------

// Checkpoint: two fixed, independently checksummed records in one file.
// Every save writes the ALTERNATE slot with a strictly higher
// generation, so a crash mid-write leaves the previous complete record
// intact in the other slot; on load the highest-generation record that
// validates wins.
const (
	checkpointName = "reliable.ckp"
	cpRecordSize   = 4 + 4 + 4 // generation + ack + crc32
	cpSlotCount    = 2
	checkpointSize = cpRecordSize * cpSlotCount
)

type cpRecord struct {
	generation uint32
	ack        uint32
}

func checkpointPath(dir string) string {
	return filepath.Join(dir, checkpointName)
}

func marshalCPRecord(r cpRecord) []byte {
	b := make([]byte, cpRecordSize)
	binary.BigEndian.PutUint32(b[0:4], r.generation)
	binary.BigEndian.PutUint32(b[4:8], r.ack)
	binary.BigEndian.PutUint32(b[8:12], crc32.ChecksumIEEE(b[0:8]))
	return b
}

func unmarshalCPRecord(b []byte) (cpRecord, bool) {
	var r cpRecord
	if len(b) < cpRecordSize {
		return r, false
	}
	if binary.BigEndian.Uint32(b[8:12]) != crc32.ChecksumIEEE(b[0:8]) {
		return r, false
	}
	r.generation = binary.BigEndian.Uint32(b[0:4])
	r.ack = binary.BigEndian.Uint32(b[4:8])
	return r, true
}

// loadCheckpoint returns the acknowledged "next expected" position of
// the newest valid record. A missing/empty file, or one whose records
// all fail validation, means "no checkpoint yet" (position 0): with no
// confirmed position the safe action is to replay everything the log
// holds, and the reader deduplicates the overlap.
func loadCheckpoint(dir string) (uint32, bool, error) {
	data, err := os.ReadFile(checkpointPath(dir))
	if err != nil {
		if os.IsNotExist(err) {
			return 0, false, nil
		}
		return 0, false, err
	}
	if len(data) == 0 {
		return 0, false, nil
	}

	var best cpRecord
	found := false
	for off := 0; off+cpRecordSize <= len(data); off += cpRecordSize {
		if r, ok := unmarshalCPRecord(data[off : off+cpRecordSize]); ok {
			if !found || r.generation > best.generation ||
				(r.generation == best.generation && r.ack > best.ack) {
				best = r
				found = true
			}
		}
	}
	if !found {
		return 0, false, nil
	}
	return best.ack, true, nil
}

// nextCPSlot chooses the slot to overwrite and the next generation:
// alternate slots, strictly increasing generations.
func nextCPSlot(dir string) (slot int, generation uint32, err error) {
	data, rerr := os.ReadFile(checkpointPath(dir))
	if rerr != nil && !os.IsNotExist(rerr) {
		return 0, 0, rerr
	}
	var gens [cpSlotCount]uint32
	var ok [cpSlotCount]bool
	for i := 0; i < cpSlotCount; i++ {
		lo, hi := i*cpRecordSize, (i+1)*cpRecordSize
		if len(data) >= hi {
			if r, valid := unmarshalCPRecord(data[lo:hi]); valid {
				gens[i], ok[i] = r.generation, true
			}
		}
	}
	switch {
	case !ok[0] && !ok[1]:
		return 0, 1, nil
	case ok[0] && (!ok[1] || gens[0] >= gens[1]):
		return 1, gens[0] + 1, nil
	default:
		return 0, gens[1] + 1, nil
	}
}

// saveCheckpoint writes one new record into the alternate slot. The
// other slot is untouched, so at every durable instant at least the
// previous complete record survives. The very first write sizes the
// file to both slots; later writes never touch the slot they are not
// rewriting.
func saveCheckpoint(dir string, ack uint32) error {
	slot, generation, err := nextCPSlot(dir)
	if err != nil {
		return err
	}
	path := checkpointPath(dir)

	// Size the file before the record write so the padding never lands
	// on a slot an earlier checkpoint already filled.
	needPad := true
	if info, statErr := os.Stat(path); statErr == nil && info.Size() >= checkpointSize {
		needPad = false
	}

	f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE, 0o644)
	if err != nil {
		return err
	}
	defer f.Close()

	if needPad {
		if _, err := f.WriteAt(make([]byte, checkpointSize), 0); err != nil {
			return err
		}
	}
	if _, err := f.WriteAt(marshalCPRecord(cpRecord{generation: generation, ack: ack}),
		int64(slot*cpRecordSize)); err != nil {
		return err
	}
	return f.Sync()
}

// ----------------------------------------------------------------------
// Replay log: appended, length-prefixed, CRC'd records in sequence
// order. Scanning is strict: every byte must belong to one complete,
// valid record. A truncated file or a flipped bit therefore fails with
// ErrChecksum instead of silently delivering or skipping frames.
//
// Record layout:
//
//	+---------+---------+----------+--------+----------+=========+
//	| seq (4) | kind(1) | flags(2) | len(4) | crc32(4) | payload |
//	+---------+---------+----------+--------+----------+=========+
//
// The CRC covers the 11 header bytes and the payload.
// ----------------------------------------------------------------------

const (
	logName    = "reliable.log"
	logHdrSize = 4 + 1 + 2 + 4 + 4
)

type logRecord struct {
	seq uint32
	f   ReliableFrame
}

type replayLog struct {
	path string
	mu   sync.Mutex
	recs []logRecord
}

func openReplayLog(dir string) (*replayLog, error) {
	l := &replayLog{path: filepath.Join(dir, logName)}
	if err := l.load(); err != nil {
		return nil, err
	}
	return l, nil
}

func (l *replayLog) load() error {
	data, err := os.ReadFile(l.path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return err
	}

	for off := 0; off < len(data); {
		// Any bytes that do not form a complete, valid record are a
		// truncated tail: strict failure, no further delivery.
		if len(data)-off < logHdrSize {
			return fmt.Errorf("codec: replay log %s truncated: %w", logName, ErrChecksum)
		}
		hdr := data[off : off+logHdrSize]
		seq := binary.BigEndian.Uint32(hdr[0:4])
		kind := hdr[4]
		flags := binary.BigEndian.Uint16(hdr[5:7])
		plen := int(binary.BigEndian.Uint32(hdr[7:11]))
		wantCRC := binary.BigEndian.Uint32(hdr[11:15])

		end := off + logHdrSize + plen
		if plen < 0 || end > len(data) {
			return fmt.Errorf("codec: replay log %s truncated: %w", logName, ErrChecksum)
		}
		h := crc32.NewIEEE()
		h.Write(hdr[:11])
		h.Write(data[off+logHdrSize : end])
		if h.Sum32() != wantCRC {
			return fmt.Errorf("codec: replay log %s corrupted: %w", logName, ErrChecksum)
		}

		payload := make([]byte, plen)
		copy(payload, data[off+logHdrSize:end])
		l.recs = append(l.recs, logRecord{
			seq: seq,
			f:   ReliableFrame{Flags: flags, Kind: kind, Payload: payload},
		})
		off = end
	}
	return nil
}

// append journals one frame as a single fully checksummed record.
func (l *replayLog) append(seq uint32, f ReliableFrame) error {
	l.mu.Lock()
	defer l.mu.Unlock()

	hdr := make([]byte, logHdrSize)
	binary.BigEndian.PutUint32(hdr[0:4], seq)
	hdr[4] = f.Kind
	binary.BigEndian.PutUint16(hdr[5:7], f.Flags)
	binary.BigEndian.PutUint32(hdr[7:11], uint32(len(f.Payload)))
	h := crc32.NewIEEE()
	h.Write(hdr[:11])
	h.Write(f.Payload)
	binary.BigEndian.PutUint32(hdr[11:15], h.Sum32())

	file, err := os.OpenFile(l.path, os.O_WRONLY|os.O_CREATE|os.O_APPEND, 0o644)
	if err != nil {
		return err
	}
	// One write of the whole record keeps the on-disk tail either absent
	// or complete from the point of view of a killing crash.
	if _, err := file.Write(append(hdr, f.Payload...)); err != nil {
		file.Close()
		return err
	}
	if err := file.Sync(); err != nil {
		file.Close()
		return err
	}
	if err := file.Close(); err != nil {
		return err
	}

	l.recs = append(l.recs, logRecord{seq: seq, f: f})
	return nil
}

// bounds reports the lowest and one-past-the-highest held sequence and
// whether the log is empty.
func (l *replayLog) bounds() (base, next uint32, empty bool) {
	l.mu.Lock()
	defer l.mu.Unlock()
	if len(l.recs) == 0 {
		return 0, 0, true
	}
	return l.recs[0].seq, l.recs[len(l.recs)-1].seq + 1, false
}

// framesFrom returns the logged frames with sequence >= from, in order.
func (l *replayLog) framesFrom(from uint32) []logRecord {
	l.mu.Lock()
	defer l.mu.Unlock()
	var out []logRecord
	for _, r := range l.recs {
		if r.seq >= from {
			out = append(out, r)
		}
	}
	return out
}

// prefix discards logged frames with sequence < base (already
// acknowledged), rewriting the log atomically via temp file + rename.
func (l *replayLog) prefix(base uint32) error {
	l.mu.Lock()
	defer l.mu.Unlock()

	keep := l.recs[:0]
	for _, r := range l.recs {
		if r.seq >= base {
			keep = append(keep, r)
		}
	}
	if len(keep) == len(l.recs) {
		return nil
	}
	l.recs = keep

	tmp := l.path + ".tmp"
	f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
	if err != nil {
		return err
	}
	for _, r := range keep {
		hdr := make([]byte, logHdrSize)
		binary.BigEndian.PutUint32(hdr[0:4], r.seq)
		hdr[4] = r.f.Kind
		binary.BigEndian.PutUint16(hdr[5:7], r.f.Flags)
		binary.BigEndian.PutUint32(hdr[7:11], uint32(len(r.f.Payload)))
		h := crc32.NewIEEE()
		h.Write(hdr[:11])
		h.Write(r.f.Payload)
		binary.BigEndian.PutUint32(hdr[11:15], h.Sum32())
		if _, err := f.Write(hdr); err != nil {
			f.Close()
			return err
		}
		if _, err := f.Write(r.f.Payload); err != nil {
			f.Close()
			return err
		}
	}
	if err := f.Sync(); err != nil {
		f.Close()
		return err
	}
	if err := f.Close(); err != nil {
		return err
	}
	return os.Rename(tmp, l.path)
}

package codec

import (
	"encoding/binary"
	"io"
	"sync"
)

// flusher is implemented by buffered writers such as *bufio.Writer.
type flusher interface {
	Flush() error
}

// Session is a concurrency-safe multi-frame layer sitting on top of one
// byte writer and one byte reader. It does not change the wire format:
// every written frame is serialized with Encode and frames are simply
// concatenated, so the byte stream stays byte-for-byte compatible with
// the single-frame Encode/Decode entries.
//
// The two directions are independent and may be used concurrently:
//   - WriteFrame appends one whole encoded frame to an internal write
//     buffer; Flush writes everything buffered so far, in write order,
//     to the underlying writer.
//   - ReadFrame pulls bytes from the underlying reader in whatever
//     chunk sizes they arrive, keeps an incomplete trailing frame in an
//     internal buffer and returns one complete Frame per call.
//
// The total number of frames in a session is unbounded; the per-frame
// payload limit is MaxPayload, enforced at write time.
type Session struct {
	w io.Writer
	r io.Reader

	wmu  sync.Mutex
	wbuf []byte

	rmu  sync.Mutex
	rbuf []byte
	// terminal error of the read side: a bad frame's error, io.EOF or
	// an error reported by the underlying reader.
	rerr error
}

// NewSession returns a session writing to w and reading from r.
func NewSession(w io.Writer, r io.Reader) *Session {
	return &Session{w: w, r: r}
}

// WriteFrame encodes f with the single-frame encoder and appends the
// whole frame to the session's write buffer. Because Encode rejects an
// oversized payload before any byte is buffered, an ErrTooLarge result
// never leaves a partial frame behind, and concurrent writes never
// interleave the bytes of one frame with another. Writes become visible
// to the reader in call-arrival order once Flush runs.
func (s *Session) WriteFrame(f Frame) error {
	b, err := Encode(f)
	if err != nil {
		return err
	}
	s.wmu.Lock()
	s.wbuf = append(s.wbuf, b...)
	s.wmu.Unlock()
	return nil
}

// Flush writes every buffered frame to the underlying writer as one
// ordered run and then, if the writer implements Flush itself (for
// example *bufio.Writer), flushes it. Bytes already appended by
// WriteFrame are never reordered or split across frames. If the
// underlying writer errors after a short write, the unsent tail is
// retained and a later Flush retries it.
func (s *Session) Flush() error {
	s.wmu.Lock()
	defer s.wmu.Unlock()

	pending := s.wbuf
	for len(pending) > 0 {
		n, err := s.w.Write(pending)
		pending = pending[n:]
		if err != nil {
			// Keep the unsent tail at the front of the buffer so a
			// later WriteFrame/Flush continues from exactly this point.
			copy(s.wbuf, pending)
			s.wbuf = s.wbuf[:len(pending)]
			return err
		}
	}
	s.wbuf = s.wbuf[:0]

	if f, ok := s.w.(flusher); ok {
		return f.Flush()
	}
	return nil
}

// ReadFrame returns the next complete frame, reading more bytes from the
// underlying reader only when the buffer cannot yet supply one. A
// truncated frame at the end of the input is buffered without error
// until more bytes arrive; it is reported as ErrShortFrame only when the
// reader signals end of input with bytes still outstanding. A clean end
// of input with no residual bytes returns io.EOF, i.e. reading simply
// stops.
//
// When a complete frame is corrupt, the error is the same value Decode
// would return for that frame (ErrBadVersion, ErrChecksum or
// ErrTooLarge); frame delivery stops there and the error becomes
// sticky, while every frame returned earlier already belongs to the
// caller. Concurrent ReadFrame calls are serialized, so each frame is
// delivered exactly once.
func (s *Session) ReadFrame() (Frame, error) {
	s.rmu.Lock()
	defer s.rmu.Unlock()

	if s.rerr != nil {
		return Frame{}, s.rerr
	}

	var scratch [4096]byte

	for {
		// A frame can be handed to Decode only once its declared length
		// is fully buffered; Decode then decides every error with exactly
		// the same precedence the single-frame entry uses.
		if len(s.rbuf) >= HeaderSize {
			frameLen := uint64(HeaderSize) + uint64(binary.BigEndian.Uint32(s.rbuf[0:4]))
			if uint64(len(s.rbuf)) >= frameLen {
				f, err := Decode(s.rbuf[:int(frameLen)])
				if err != nil {
					return s.failRead(err)
				}
				// Drop the consumed frame and compact the residual bytes
				// of later frames to the front; Decode copied the payload
				// out, so overlapping storage is safe.
				rest := len(s.rbuf) - int(frameLen)
				copy(s.rbuf, s.rbuf[int(frameLen):])
				s.rbuf = s.rbuf[:rest]
				return f, nil
			}
		}

		n, err := s.r.Read(scratch[:])
		if n > 0 {
			s.rbuf = append(s.rbuf, scratch[:n]...)
		}
		if err == nil {
			// A (0, nil) read delivers no information; retry instead of
			// mistaking it for end of input.
			continue
		}
		if err == io.EOF {
			if len(s.rbuf) > 0 {
				return s.failRead(ErrShortFrame)
			}
			return s.failRead(io.EOF)
		}
		return s.failRead(err)
	}
}

// failRead records the terminal read-side error and returns it with the
// zero frame.
func (s *Session) failRead(err error) (Frame, error) {
	s.rerr = err
	return Frame{}, err
}

