296	func TestMuxQuotaFullIsOverLimitAndReleasesOnAck(t *testing.T) {
297		const W = 3
298		cfg := muxCfg(t, 2, W)
299		var wire bytes.Buffer
300		snd := newMuxSender(t, &wire, cfg)
301	
302		for i := 0; i < W; i++ {
303			if err := snd.WriteFrame(ChannelFrame{Channel: 0, Kind: uint8(i), Payload: []byte{byte('a' + i)}}); err != nil {
304				t.Fatalf("write %d: %v", i, err)
305			}
306		}
307		// Quota exactly full: the established over-limit sentinel, same
308		// value as ErrTooLarge; frame dropped, no sequence consumed.
309		err := snd.WriteFrame(ChannelFrame{Channel: 0, Kind: 99, Payload: []byte("drop")})
310		if !errors.Is(err, ErrWindowFull) || !errors.Is(err, ErrTooLarge) {
311			t.Fatalf("err = %v, want ErrWindowFull == ErrTooLarge", err)
312		}
313		// Another channel is unaffected by the full quota of channel 0.
314		if err := snd.WriteFrame(ChannelFrame{Channel: 1, Kind: 5, Payload: []byte("other")}); err != nil {
315			t.Fatalf("ch1 write while ch0 full: %v", err)
316		}
317		if err := snd.Flush(); err != nil {
318			t.Fatal(err)
319		}
320	
321		ws := parseMuxWire(t, wire.Bytes(), 0)
322		if fmt.Sprint(muxChansSeq(ws)) != "[0:0 1:0 0:1 0:2]" {
323			t.Fatalf("wire order = %v, want round-robin [0:0 1:0 0:1 0:2]", muxChansSeq(ws))
324		}
325	
326		// Ack two ch0 frames at the mux layer: two quota slots free,
327		// numbering continues at 3. The send-only reliable layer is driven
328		// directly too (as the reliable layer's own tests do), freeing its
329		// window so the resend plus the new frame all go out.
330		snd.applyAck(0, 2)
331		snd.rel.applyAck(4)
332		if err := snd.WriteFrame(ChannelFrame{Channel: 0, Kind: 99, Payload: []byte("after")}); err != nil {
333			t.Fatalf("write after ack: %v", err)
334		}
335		wire.Reset()
336		if err := snd.Flush(); err != nil {
337			t.Fatal(err)
338		}
339		var ch0 []uint32
340		for _, w := range parseMuxWire(t, wire.Bytes(), 0) {
341			if w.ch == 0 {
342				ch0 = append(ch0, w.seq)
343			}
344		}
345		// Acked 0,1 never reappear; 2 is the still-in-flight retransmit and
346		// 3 is the new frame, proving the rejected write consumed no seq.
347		if fmt.Sprint(ch0) != "[2 3]" {
348			t.Fatalf("ch0 seqs = %v, want [2 3]", ch0)
349		}
350	}
