695		if err != nil {
696			t.Fatal(err)
697		}
698		s1, err := NewMux(rel1, cfg)
699		if err != nil {
700			t.Fatal(err)
701		}
702		for i := 0; i < 4; i++ {
703			if err := s1.WriteFrame(ChannelFrame{Channel: 0, Kind: uint8(i), Payload: []byte(fmt.Sprintf("a%d", i))}); err != nil {
704				t.Fatal(err)
705			}
706		}
707		for i := 0; i < 2; i++ {
708			if err := s1.WriteFrame(ChannelFrame{Channel: 1, Kind: uint8(i), Payload: []byte(fmt.Sprintf("b%d", i))}); err != nil {
709				t.Fatal(err)
710			}
711		}
712		if err := s1.Flush(); err != nil {
713			t.Fatal(err)
714		}
715	
716		f := newFeed()
717		rcvCfg := MuxConfig{Channels: 2, Window: 4, StateDir: filepath.Join(dir, "rcv")}
718		rcvRelCfg := ReliableConfig{Window: 32, StateDir: filepath.Join(dir, "rcv", "rel")}
719		rcvR, err := NewReliable(NewSession(io.Discard, f), rcvRelCfg)
720		if err != nil {
721			t.Fatal(err)
722		}
723		rcv, err := NewMux(rcvR, rcvCfg)
724		if err != nil {
725			t.Fatal(err)
726		}
727		f.replace(wire1.Bytes())
728		// Peer confirms a0,a1 and b0 before the drop.
729		first := drainMux(t, rcv, 3)
730		if len(first) != 3 {
731			t.Fatalf("got %d frames, want 3", len(first))
732		}
733		s1.applyAck(0, 2)
734		s1.applyAck(1, 1)
735		if err := s1.Close(); err != nil {
736			t.Fatal(err)
737		}
738		if err := rel1.Close(); err != nil {
739			t.Fatal(err)
740		}
741	
742		// Restart with the same state directory: only unacked frames go out
743		// (ch0 2,3; ch1 1), round-robin from channel 0.
744		var wire2 bytes.Buffer
745		rel2, err := NewReliable(NewSession(&wire2, closedReader{}), relCfg)
746		if err != nil {
747			t.Fatal(err)
748		}
749		s2, err := NewMux(rel2, cfg)
750		if err != nil {
751			t.Fatalf("restart: %v", err)
752		}
753		if s2.sc[0].acked != 2 || s2.sc[0].next != 4 || s2.sc[1].acked != 1 || s2.sc[1].next != 2 {
754			t.Fatalf("positions = ch0 %d/%d ch1 %d/%d, want 2/4 and 1/2",
755				s2.sc[0].acked, s2.sc[0].next, s2.sc[1].acked, s2.sc[1].next)
756		}
757		if err := s2.Flush(); err != nil {
758			t.Fatal(err)
759		}
