761		if fmt.Sprint(muxChansSeq(rest)) != "[0:2 1:1 0:3]" {
762			t.Fatalf("resent = %v, want [0:2 1:1 0:3]", muxChansSeq(rest))
763		}
764	
765		// New writes continue numbering past the journal tail per channel.
766		if err := s2.WriteFrame(ChannelFrame{Channel: 0, Payload: []byte("a4")}); err != nil {
767			t.Fatal(err)
768		}
769		if s2.sc[0].next != 5 {
