958	func TestMuxConcurrentWritersDifferentChannels(t *testing.T) {
959		const C, W, per = 4, 400, 200
960		cfg := muxCfg(t, C, W)
961		var wire bytes.Buffer
962		snd := newMuxSender(t, &wire, cfg)
963	
964		var wg sync.WaitGroup
965		for g := 0; g < C; g++ {
966			wg.Add(1)
967			go func(g int) {
968				defer wg.Done()
969				for i := 0; i < per; i++ {
970					payload := []byte(fmt.Sprintf("g%di%d", g, i))
971					for {
972						err := snd.WriteFrame(ChannelFrame{
973							Channel: uint16(g), Kind: uint8(g), Payload: payload,
974						})
975						if err == nil {
976							break
977						}
978						if !errors.Is(err, ErrWindowFull) {
979							t.Errorf("write: %v", err)
980							return
981						}
982						// No acks move in this send-only test; once a
983						// channel fills, stop: bounded buffer verified
984						// elsewhere. Just make the accepted count check
985						// below possible by writing per<=W.
986						return
987					}
988				}
989			}(g)
990		}
991		wg.Wait()
992		if err := snd.Flush(); err != nil {
993			t.Fatal(err)
994		}
995	
996		// Every frame decodes whole (no interleaving), per-channel seqs are
997		// contiguous from 0 and counts match accepted writes.
998		ws := parseMuxWire(t, wire.Bytes(), 0)
999		counts := map[uint16]int{}
1000		seqs := map[uint16]map[uint32]bool{}
1001		for _, w := range ws {
1002			counts[w.ch]++
1003			if seqs[w.ch] == nil {
1004				seqs[w.ch] = map[uint32]bool{}
1005			}
1006			if seqs[w.ch][w.seq] {
1007				t.Fatalf("ch %d seq %d sent twice", w.ch, w.seq)
1008			}
1009			seqs[w.ch][w.seq] = true
1010		}
1011		for g := 0; g < C; g++ {
1012			if counts[uint16(g)] != per {
1013				t.Fatalf("ch %d sent %d frames, want %d", g, counts[uint16(g)], per)
1014			}
1015			for i := uint32(0); i < per; i++ {
1016				if !seqs[uint16(g)][i] {
1017					t.Fatalf("ch %d missing seq %d", g, i)
1018				}
1019			}
1020		}
1021	}
