1023	func TestMuxFullDuplex(t *testing.T) {
1024		a, b := net.Pipe()
1025		dir := t.TempDir()
1026		mk := func(conn net.Conn, sub string) *Mux {
1027			rel, err := NewReliable(NewSession(conn, conn), ReliableConfig{
1028				Window: 256, StateDir: filepath.Join(dir, sub, "rel")})
1029			if err != nil {
1030				t.Fatal(err)
1031			}
1032			m, err := NewMux(rel, MuxConfig{Channels: 3, Window: 64, StateDir: filepath.Join(dir, sub)})
1033			if err != nil {
1034				t.Fatal(err)
1035			}
1036			t.Cleanup(func() { m.Close(); rel.Close() })
1037			return m
1038		}
1039		ma := mk(a, "a")
1040		mb := mk(b, "b")
1041	
1042		const perCh = 40
1043		got := make(map[uint16][]string)
1044		var gotMu sync.Mutex
1045		allDone := make(chan struct{})
1046	
1047		// A reads only acks.
1048		go func() {
1049			for {
1050				if _, err := ma.ReadFrame(); err != nil {
1051					return
1052				}
1053			}
1054		}()
1055	
1056		// B collects data by channel until perCh frames on each of 3
1057		// channels, plus the three EOFs.
1058		go func() {
1059			defer close(allDone)
1060			for {
1061				cf, err := mb.ReadFrame()
1062				if err != nil {
1063					if errors.Is(err, io.EOF) {
1064						gotMu.Lock()
1065						tag := "EOF:" + fmt.Sprint(cf.Channel)
1066						got[99] = append(got[99], tag)
1067						done := len(got[0]) == perCh && len(got[1]) == perCh && len(got[2]) == perCh && len(got[99]) == 3
1068						gotMu.Unlock()
1069						if done {
1070							return
1071						}
1072						continue
1073					}
1074					return
1075				}
1076				gotMu.Lock()
1077				got[cf.Channel] = append(got[cf.Channel], string(cf.Payload))
1078				gotMu.Unlock()
1079			}
1080		}()
1081	
1082		for ch := 0; ch < 3; ch++ {
1083			for i := 0; i < perCh; i++ {
1084				if err := ma.WriteFrame(ChannelFrame{
1085					Channel: uint16(ch), Kind: uint8(ch), Payload: []byte(fmt.Sprintf("c%d-%04d", ch, i)),
1086				}); err != nil {
1087					t.Fatalf("write ch%d i%d: %v", ch, i, err)
1088				}
1089				if i%9 == 0 {
1090					if err := ma.Flush(); err != nil {
1091						t.Fatal(err)
1092					}
1093				}
1094			}
1095		}
1096		for ch := 0; ch < 3; ch++ {
1097			if err := ma.CloseChannel(uint16(ch)); err != nil {
1098				t.Fatal(err)
1099			}
1100		}
1101		if err := ma.Flush(); err != nil {
1102			t.Fatal(err)
1103		}
1104	
1105		<-allDone
1106		a.Close()
1107		b.Close()
1108	
1109		gotMu.Lock()
1110		defer gotMu.Unlock()
1111		for ch := 0; ch < 3; ch++ {
1112			if len(got[uint16(ch)]) != perCh {
1113				t.Fatalf("ch %d got %d frames, want %d", ch, len(got[uint16(ch)]), perCh)
1114			}
1115			for i, p := range got[uint16(ch)] {
1116				if want := fmt.Sprintf("c%d-%04d", ch, i); p != want {
1117					t.Fatalf("ch %d frame %d = %q, want %q (order/dup changed)", ch, i, p, want)
1118				}
1119			}
