346		}()
347	
348		// The big message is accepted in one call even though its fragments
349		// span several windows.
350		if err := fa.WriteFrame(FragFrame{Channel: 0, Kind: 7, Payload: big}); err != nil {
351			t.Fatalf("big write: %v", err)
352		}
353		waitQuota := func(step string) {
354			t.Helper()
355			for {
356				select {
357				case res := <-resCh:
358					t.Fatalf("collector exited during %s: err=%v big=%d smalls=%d eofs=%v",
359						step, res.err, len(res.big), len(res.smalls), res.eofs)
360				case <-time.After(10 * time.Second):
361					t.Fatalf("timed out during %s", step)
362				default:
363				}
364				var err error
365				switch step {
366				case "close0":
367					err = fa.CloseChannel(0)
368				case "close1":
369					err = fa.CloseChannel(1)
370				}
371				if err == nil {
372					return
373				}
374				if !errors.Is(err, ErrWindowFull) {
375					t.Fatalf("%s: %v", step, err)
376				}
377				time.Sleep(time.Millisecond)
378			}
379		}
380		for i := 0; i < smalls; i++ {
381			payload := []byte(fmt.Sprintf("s%02d", i))
382			for {
383				select {
384				case res := <-resCh:
385					t.Fatalf("collector exited during small %d: err=%v", i, res.err)
386				case <-time.After(10 * time.Second):
387					t.Fatalf("timed out during small %d", i)
388				default:
389				}
390				err := fa.WriteFrame(FragFrame{Channel: 1, Kind: uint8(i), Payload: payload})
391				if err == nil {
392					break
393				}
394				if !errors.Is(err, ErrWindowFull) {
395					t.Fatalf("small write %d: %v", i, err)
396				}
397				time.Sleep(time.Millisecond)
398			}
399		}
400		waitQuota("close0")
401		waitQuota("close1")
402	
403		res := <-resCh
404		a.Close()
405		b.Close()
406		close(flushStop)
407		<-flusherDone
408	
409		if res.err != nil {
410			t.Fatalf("collector read error: %v", res.err)
411		}
412		if !bytes.Equal(res.big, big) {
413			t.Fatalf("big message: got %d bytes, equal=%v", len(res.big), bytes.Equal(res.big, big))
414		}
415		if len(res.smalls) != smalls {
416			t.Fatalf("smalls = %d, want %d", len(res.smalls), smalls)
417		}
418		for i, s := range res.smalls {
419			if want := fmt.Sprintf("s%02d", i); s != want {
420				t.Fatalf("small %d = %q, want %q", i, s, want)
421			}
422		}
423		if len(res.eofs) != 2 {
424			t.Fatalf("eofs = %v, want 2", res.eofs)
425		}
426	}
